 function scanning(){if(mode!=='world')return;if(terrain.active&&!ExoWorld.portal(unit)&&!ExoWorld.cave){Exo.terrainProbe();return;}if(combat.trial){combat.message='这里是战斗练习区。回到自由探索后，就能扫描地标并保存发现。';document.getElementById('exo-radio').textContent=combat.message;return;}if(fireCourse.active){Exo.courseCycle();return;}if((typeof ExoTrainingGround!=='undefined'&&!ExoWorld.cave&&ExoTrainingGround.near(unit))||ExoGreenTrail.near(unit)||ExoWorld.portal(unit)||ExoWorld.cave||ExoWorld.buildingPortal?.(unit)){interact();return}if(ExoCanyonV2.inZone(unit.x,unit.y)){document.getElementById('exo-radio').textContent='这里是 K–09 旧河谷。沿青绿灯走向撤离机库；靠近灯箱或路边遗留的物件，按 E 查看。';return;}scan={x:unit.x,y:unit.y,time:performance.now()};sound(720,.6);const near=M.sites.map((s,i)=>({s,i,d:Math.hypot(s.x-unit.x,s.y-unit.y)})).sort((a,b)=>a.d-b.d)[0];let message;if(near.d<195){journey.award('beacon:'+near.i);found.add(near.i);try{localStorage.setItem('exo-discoveries-v1',JSON.stringify([...found]))}catch{}message=`已记录：${near.s.name} · ${near.s.type}。${near.s.desc}`;document.getElementById('exo-count').textContent=`已发现 ${found.size} / 6 处地标`;if(found.size===6)message+=' 六处地标都找到了！接下来可以自由探索。'}else{const f=ExoWorld.features.find(f=>Math.hypot((unit.x-f.x)/f.rx,(unit.y-f.y)/f.ry)<1.4);message=f?`${f.name}：${f.text}`:`这里还没有发现信标。最近信标距离 ${Math.round(near.d)} 米，请继续靠近。`; }document.getElementById('exo-radio').textContent=message}
