 function trackJourney(){
  const o=journey.objective();if(o.finished){journal('records');return;}
  if(o.action.kind==='lesson'){closeModal();if(o.action.id===1)Exo.firstMission();else Exo.terrainPanel();return;}
  if(ExoWorld.interior&&o.action.kind==='facility'&&ExoWorld.interior.structure.id===o.action.id){Exo.travel();return;}
  const p=journey.targetFor(o.action);if(!p){journal();return;}
  const underground=!!ExoWorld.cave;
  terminal('journey','<div class="exp-journal"><div class="exp-eyebrow">第一卷 / 实地调查</div><h2>'+p.name+'</h2><p>'+o.detail+'</p><p class="exp-hint">X '+Math.round(p.x)+' / Y '+Math.round(p.y)+' · 地表坐标</p><p>'+(underground?'你现在在地下。先打开地图找到出口，回到地表后就能设置路线。':'路线会先带你走上道路。最后一段只指向目的地，需要自己绕过岩壁和建筑；到了开阔处也可以起飞。')+'</p><div class="fc-buttons">'+(!underground?'<button class="primary" onclick="Exo.navigateStory()">沿道路导航</button>':'<button onclick="Exo.travel()">查看地下地图</button>')+(o.action.kind==='facility'?'<button onclick="closeModal();Exo.visitFacility(\''+o.action.id+'\')">直接到达设施入口</button>':'')+'<button onclick="Exo.journal()">返回当前任务</button></div></div>');
 }
