 function beginTraining(kind){
  if(kind==='terrain'){Exo.terrainResume();Exo.terrainTrack();return;}
  const station=ExoTrainingGround.terminals.find(p=>p.id===kind);if(!station)return;
  if(ExoWorld.cave||unit.flight||Math.hypot(unit.x-station.x,unit.y-station.y)>180){visitTraining(kind);return;}
  if(kind==='fire'){terminal('training',ExoFireControl.brief(fireCourse),'EP 07 · 老林的瞄准课');}else{Exo.terrainResume();}
 }
